"""Crypto migration must retain issued tokens, not authentication weaknesses."""

import base64
import hmac
import importlib
import inspect
import json
from datetime import datetime, timedelta, timezone

import httpx
import pytest

from xagent.web import jwt_codec as jwt

SECRET = "compatibility-secret-with-at-least-32-bytes"


def test_pre_migration_python_jose_token_remains_valid():
    # Fixed fixture generated by python-jose 3.5.0, not the replacement library.
    token = (
        "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9."
        "eyJzdWIiOiJsZWdhY3ktdXNlciIsInVzZXJfaWQiOjcsInR5cGUiOiJhY2Nlc3MiLCJleHAiOjQxMDI0NDQ4MDB9."
        "zEfNdvSRd5wTCTUUBXctar_-5nW0JjsRmv5tlLnpwuo"
    )
    assert jwt.decode(
        token, "legacy-compatibility-secret-at-least-32-bytes", algorithms=["HS256"]
    ) == {"sub": "legacy-user", "user_id": 7, "type": "access", "exp": 4102444800}


@pytest.mark.parametrize("claim", ["exp", "nbf", "iat"])
@pytest.mark.parametrize("value", [None, [], {}, "not-a-number"])
def test_malformed_temporal_claim_is_a_jwt_error(claim, value):
    token = jwt.encode({claim: value}, SECRET, algorithm="HS256")
    with pytest.raises(jwt.JWTError):
        jwt.decode(token, SECRET, algorithms=["HS256"])


def test_expired_and_wrong_algorithm_tokens_are_rejected():
    token = jwt.encode(
        {"exp": datetime.now(timezone.utc) - timedelta(minutes=1)},
        SECRET,
        algorithm="HS256",
    )
    with pytest.raises(jwt.ExpiredSignatureError):
        jwt.decode(token, SECRET, algorithms=["HS256"])
    with pytest.raises(jwt.JWTError):
        jwt.decode(token, SECRET, algorithms=["HS512"])


@pytest.mark.parametrize(
    "module_name,class_name", [("zhipuai", "ZhipuAI"), ("zai", "ZaiClient")]
)
@pytest.mark.parametrize("raw_key", [True, False])
def test_retained_sdk_signatures_remain_compatible(module_name, class_name, raw_key):
    secret = "sdk-test-secret-with-at-least-32-characters"
    seen = []

    def send(request):
        seen.append(request)
        return httpx.Response(
            200,
            json={
                "id": "completion",
                "created": 1,
                "model": "test-model",
                "usage": {
                    "prompt_tokens": 1,
                    "completion_tokens": 1,
                    "total_tokens": 2,
                },
                "choices": [
                    {
                        "index": 0,
                        "finish_reason": "stop",
                        "message": {"role": "assistant", "content": "ok"},
                    }
                ],
            },
        )

    with httpx.Client(transport=httpx.MockTransport(send)) as transport:
        client_type = getattr(importlib.import_module(module_name), class_name)
        options = {}
        if "disable_token_cache" in inspect.signature(client_type).parameters:
            options["disable_token_cache"] = raw_key
        elif raw_key:
            pytest.skip("This locked SDK version only supports signed credentials")
        client = client_type(
            api_key=f"test-id.{secret}", http_client=transport, **options
        )
        result = client.chat.completions.create(
            model="test-model", messages=[{"role": "user", "content": "test"}]
        )
        assert result.choices[0].message.content == "ok"
    token = seen[0].headers["Authorization"].removeprefix("Bearer ")
    if raw_key:
        assert token == f"test-id.{secret}"
        return
    header, payload, signature = token.split(".")
    unsigned = f"{header}.{payload}".encode()
    expected = (
        base64.urlsafe_b64encode(hmac.digest(secret.encode(), unsigned, "sha256"))
        .rstrip(b"=")
        .decode()
    )
    assert signature == expected
    assert json.loads(base64.urlsafe_b64decode(payload + "==="))["api_key"] == "test-id"
    assert jwt.decode(token, secret, algorithms=["HS256"])["api_key"] == "test-id"
